import {makePanel,communityRequest} from './panels.js';
import {guidePlaces,gardenPresets} from './world-guide-data.js';
const guide=makePanel('guide-panel','공간 안내','<form><label>목적지<input maxlength="240" placeholder="온천, 스키장, 우체국…" required></label><button>찾기</button><output role="status"></output></form><div class="guide-choices panel-row"></div>');
for(const panel of [guide]){const note=document.createElement('small');note.className='ai-notice';note.textContent='입력한 내용은 안내를 위해 OpenAI로 전송됩니다.';panel.dialog.querySelector('.panel-scroll').append(note);}
async function assist(kind,extra={}){await window.joinSharedActivity();return communityRequest('assist',{kind,...extra});}
window.openWorldGuide=()=>guide.open();
const mapButton=document.createElement('button');mapButton.className='panel-primary';mapButton.textContent='공간 안내';mapButton.onclick=()=>guide.open();document.querySelector('#pane-map').append(mapButton);
const choices=guide.dialog.querySelector('.guide-choices');for(const place of guidePlaces){const button=document.createElement('button');button.textContent=place.name;button.onclick=()=>travel(place.id);choices.append(button);}
function travel(id){guide.close();const studio=document.querySelector('#studio');if(studio.open)document.querySelector('#close-studio').click();window.travelToPlace?.(id);}
guide.dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const output=guide.dialog.querySelector('output');output.textContent='찾는 중…';try{const result=await assist('guide',{text:guide.dialog.querySelector('input').value}),place=guidePlaces.find(p=>p.id===result.destination);output.textContent=result.text+(result.mode==='fallback'?' · 기본 안내':'');const go=document.createElement('button');go.textContent=place.name+' 이동';go.onclick=()=>travel(place.id);output.append(document.createElement('br'),go);}catch(error){output.textContent=error.message;}};
const garden=makePanel('garden-panel','온실 조명','<div class="panel-row"></div><output role="status"></output>');window.openGardenChoices=()=>garden.open();for(const [key,preset]of Object.entries(gardenPresets)){const button=document.createElement('button');button.textContent=preset.name;button.onclick=async()=>{window.dispatchEvent(new CustomEvent('lab:garden-light',{detail:preset.color}));const output=garden.dialog.querySelector('output');output.textContent=preset.text;try{const result=await assist('garden',{text:key});output.textContent=result.text+(result.mode==='fallback'?' · 기본 안내':'');window.dispatchEvent(new CustomEvent('lab:garden-light',{detail:gardenPresets[result.lighting].color}));}catch{}};garden.dialog.querySelector('.panel-row').append(button);}
window.explainQuiz=async(id,container)=>{let output=container.querySelector('.quiz-more');if(!output){output=document.createElement('p');output.className='quiz-more';container.append(output);}output.textContent='해설 확인 중…';try{const result=await assist('quiz',{questionId:id});output.textContent=result.text+(result.mode==='fallback'?' · 검증된 기본 해설':'');}catch(error){output.textContent=error.message;}};
const wishForm=document.querySelector('#wish-form'),recommend=document.createElement('button');recommend.type='button';recommend.textContent='장식 추천';const notice=document.createElement('small');notice.className='ai-notice';notice.textContent='장식 추천을 누르면 소원 내용이 OpenAI로 전송됩니다.';wishForm.append(notice);wishForm.querySelector('button[type=submit]').before(recommend);recommend.onclick=async()=>{const output=wishForm.querySelector('output'),text=wishForm.elements.message.value.trim();if(!text){output.textContent='소원을 먼저 입력해 주세요.';return;}recommend.disabled=true;try{const result=await assist('wish',{text});output.textContent=result.text+(result.mode==='fallback'?' · 기본 추천':'');window.dispatchEvent(new CustomEvent('lab:decoration-choice',{detail:result}));}catch(error){output.textContent=error.message;}finally{recommend.disabled=false;}};
const eventButton=document.createElement('button');eventButton.id='world-event';eventButton.hidden=true;document.body.append(eventButton);let active=null;eventButton.onclick=()=>active?.kind==='quiz'?window.openQuickQuiz?.():window.travelToPlace?.('tree');
async function events(){if(!window.labSocialJoined||document.hidden)return;try{const {events:items}=await communityRequest('events'),now=Date.now();active=items.find(e=>e.startsAt<=now&&e.endsAt>now)||null;const time=new Date(now+9*3600000),hour=time.getUTCHours();if(!active&&hour>=18&&hour<24&&time.getUTCMinutes()<2)active={kind:'lights',title:'트리 라이트 쇼'};window.labLiveEvent=active;eventButton.hidden=!active;if(active)eventButton.textContent=active.title;}catch{}}
window.addEventListener('lab:access',events);setInterval(events,30000);events();
